import React, { useEffect, useState } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Register from './pages/Register';
import MdpOublie from './pages/MdpOublie';
import CommentairesPage from './pages/Commentaires';
import Profil from './pages/Profile';
import { utilisateurService } from './services/utilisateurService';

// Composant de protection des routes
const PrivateRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
    const userId = sessionStorage.getItem('userId');

    useEffect(() => {
        const checkAuth = async () => {
            if (userId) {
                try {
                    await utilisateurService.getCurrentUser();
                    setIsAuthenticated(true);
                } catch (error) {
                    // Session invalide, nettoyer
                    sessionStorage.removeItem('userId');
                    setIsAuthenticated(false);
                }
            } else {
                setIsAuthenticated(false);
            }
        };
        checkAuth();
    }, [userId]);

    if (isAuthenticated === null) {
        return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
            <div>Chargement...</div>
        </div>;
    }

    return isAuthenticated ? <>{children}</> : <Navigate to="/login" replace />;
};

// Composant pour les routes publiques
const PublicRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
    const userId = sessionStorage.getItem('userId');

    useEffect(() => {
        const checkAuth = async () => {
            if (userId) {
                try {
                    await utilisateurService.getCurrentUser();
                    setIsAuthenticated(true);
                } catch (error) {
                    sessionStorage.removeItem('userId');
                    setIsAuthenticated(false);
                }
            } else {
                setIsAuthenticated(false);
            }
        };
        checkAuth();
    }, [userId]);

    if (isAuthenticated === null) {
        return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
            <div>Chargement...</div>
        </div>;
    }

    return isAuthenticated ? <Navigate to="/profil" replace /> : <>{children}</>;
};

function App() {
    // Solution 2: Nettoyer les sessions invalides au démarrage
    useEffect(() => {
        const validateSession = async () => {
            const userId = sessionStorage.getItem('userId');
            if (userId) {
                try {
                    await utilisateurService.getCurrentUser();
                } catch (error) {
                    // Session invalide, nettoyer
                    sessionStorage.removeItem('userId');
                    console.log('Session invalide, nettoyage effectué');
                }
            }
        };
        validateSession();
    }, []);

    return (
        <Routes>
            {/* Route par défaut : redirige vers login */}
            <Route path="/" element={<Navigate to="/login" replace />} />

            {/* Routes publiques */}
            <Route path="/login" element={
                <PublicRoute>
                    <Login />
                </PublicRoute>
            } />
            <Route path="/inscription" element={
                <PublicRoute>
                    <Register />
                </PublicRoute>
            } />
            <Route path="/mdpOublie" element={
                <PublicRoute>
                    <MdpOublie />
                </PublicRoute>
            } />

            {/* Routes privées */}
            <Route path="/profil" element={
                <PrivateRoute>
                    <Profil />
                </PrivateRoute>
            } />
            <Route path="/commentaires" element={
                <PrivateRoute>
                    <CommentairesPage />
                </PrivateRoute>
            } />

            {/* Route 404 */}
            <Route path="*" element={<Navigate to="/login" replace />} />
        </Routes>
    );
}

export default App;
